from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {c: i for i, c in enumerate(alphabet)}

    # Aho-Corasick trie construction
    nxt: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            if nxt[node][c] == -1:
                nxt[node][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            node = nxt[node][c]
        bad[node] = True

    # Build failure links and complete DFA transitions
    fail = [0] * len(nxt)
    q = deque()
    for c in range(k):
        if nxt[0][c] != -1:
            q.append(nxt[0][c])
        else:
            nxt[0][c] = 0

    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for c in range(k):
            v = nxt[u][c]
            if v != -1:
                fail[v] = nxt[fail[u]][c]
                q.append(v)
            else:
                nxt[u][c] = nxt[fail[u]][c]

    # Map non-bad states to compact indices
    good_idx = [-1] * len(nxt)
    g = 0
    for i, is_bad in enumerate(bad):
        if not is_bad:
            good_idx[i] = g
            g += 1

    if g == 0 or good_idx[0] == -1:
        return 0

    # Build transition matrix among good states
    mat = [[0] * g for _ in range(g)]
    for u in range(len(nxt)):
        ui = good_idx[u]
        if ui == -1:
            continue
        for c in range(k):
            vi = good_idx[nxt[u][c]]
            if vi != -1:
                mat[ui][vi] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * g for _ in range(g)]
        for i in range(g):
            row_a = a[i]
            row_res = res[i]
            for m in range(g):
                val = row_a[m]
                if val:
                    row_b = b[m]
                    for j in range(g):
                        row_res[j] = (row_res[j] + val * row_b[j]) % MOD
        return res

    # Binary exponentiation: compute vec * mat^n
    vec = [0] * g
    vec[good_idx[0]] = 1
    base = mat
    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * g
            for i in range(g):
                if vec[i]:
                    row = base[i]
                    for j in range(g):
                        new_vec[j] = (new_vec[j] + vec[i] * row[j]) % MOD
            vec = new_vec
        exp >>= 1
        if exp > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
